if (points.size() <= 1) return points;

std::sort(points.begin(), points.end(),
    [](const Point_2& a, const Point_2& b) {
        return a.x() < b.x() || (a.x() == b.x() && a.y() < b.y());
    });

Point_2 p0 = points[0];
std::vector<Point_2> hull;
hull.reserve(points.size());

auto orientation = [](const Point_2& a, const Point_2& b, const Point_2& c) {
    return CGAL::cross_product(b - a, c - a).y();
};

auto compare = [&](const Point_2& a, const Point_2& b) {
    double o = orientation(p0, a, b);
    if (o == 0) {
        return CGAL::squared_distance(p0, a) < CGAL::squared_distance(p0, b);
    }
    return o > 0;
};

std::sort(points.begin() + 1, points.end(), compare);

hull.push_back(points[0]);
hull.push_back(points[1]);

for (std::size_t i = 2; i < points.size(); ++i) {
    while (hull.size() >= 2 &&
           orientation(hull[hull.size() - 2], hull.back(), points[i]) <= 0) {
        hull.pop_back();
    }
    hull.push_back(points[i]);
}

return hull;

